document.querySelectorAll('.load-contact-map').forEach(button=>button.addEventListener('click',()=>{const frame=document.createElement('iframe');frame.title=document.documentElement.lang==='en'?'EKS LKW location — Șoseaua Viilor 54':'Locație EKS LKW — Șoseaua Viilor 54';frame.referrerPolicy='no-referrer';frame.loading='lazy';frame.allowFullscreen=true;frame.src='https://www.google.com/maps?cid=3169278761931680726&q=EKS%20LKW%20PIESE%20AUTO%2C%20%C8%98oseaua%20Viilor%2054%2C%20Bucure%C8%99ti&z=17&output=embed';button.closest('.contact-map').replaceChildren(frame)}));
